'use client'

import { useState, useEffect } from 'react'
import { supabase } from '@/lib/supabase'
import { Send, CheckCircle, AlertCircle, X } from 'lucide-react'
import MainMenu from '@/components/MainMenu'

export default function Contribuer() {
  const [formData, setFormData] = useState({
    nomLieu: '',
    typesDeLieux: [],
    ville: '',
    description: '',
    email: ''
  })
  const [status, setStatus] = useState(null)
  const [loading, setLoading] = useState(false)
  const [categories, setCategories] = useState([])
  const [villes, setVilles] = useState([])
  const [typeInput, setTypeInput] = useState('')
  const [showTypeSuggestions, setShowTypeSuggestions] = useState(false)
  const [selectedSuggestionIndex, setSelectedSuggestionIndex] = useState(-1)

  const TAG_COLORS = [
    "#9FFFCA",
    "#FFAEFF",
    "#FFAC88",
    "#C6BBFF",
    "#F9FFBD",
    "#A8FFD8",
    "#FC9F9F",
    "#FF8FD4",
    "#FFB7E3",
    "#FFB39A",
    "#FFD1B8",
    "#B8C7FF",
    "#D6D0FF",
    "#FFF3A0",
    "#EFFF9F",
    "#8FD6FF",
    "#AEE8FF",
    "#BFF2E8",
    "#FFDDEB",
  ]

  function getColorForType(type) {
    let hash = 0
    for (let i = 0; i < type.length; i++) {
      hash = type.charCodeAt(i) + ((hash << 5) - hash)
    }
    return TAG_COLORS[Math.abs(hash) % TAG_COLORS.length]
  }

  const normalizeString = (str) => {
    if (!str || typeof str !== 'string') return ''
    return str
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim()
  }

  useEffect(() => {
    loadData()
  }, [])

  const loadData = async () => {
    const { data: categoriesData } = await supabase
      .from('categories')
      .select('nom')
      .order('nom', { ascending: true })
    
    const { data: villesData } = await supabase
      .from('villes')
      .select('nom')
      .order('nom', { ascending: true })
    
    if (categoriesData) setCategories(categoriesData.map(c => c.nom))
    if (villesData) setVilles(villesData.map(v => v.nom))
  }

  const getTypeSuggestions = () => {
    if (!typeInput) return []
    
    const normalized = normalizeString(typeInput)
    return categories
      .filter(c => !formData.typesDeLieux.includes(c))
      .filter(c => normalizeString(c).includes(normalized))
      .sort((a, b) => {
        const aNorm = normalizeString(a)
        const bNorm = normalizeString(b)
        const aStarts = aNorm.startsWith(normalized)
        const bStarts = bNorm.startsWith(normalized)
        if (aStarts && !bStarts) return -1
        if (!aStarts && bStarts) return 1
        return a.localeCompare(b)
      })
  }

  const handleTypeInputKeyDown = (e) => {
    const suggestions = getTypeSuggestions()
    
    if (e.key === 'Tab' && suggestions.length > 0) {
      e.preventDefault()
      const selectedType = selectedSuggestionIndex >= 0 
        ? suggestions[selectedSuggestionIndex] 
        : suggestions[0]
      ajouterType(selectedType)
    } else if (e.key === 'ArrowDown') {
      e.preventDefault()
      setSelectedSuggestionIndex(prev => 
        prev < suggestions.length - 1 ? prev + 1 : prev
      )
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setSelectedSuggestionIndex(prev => prev > 0 ? prev - 1 : -1)
    } else if (e.key === 'Enter' && selectedSuggestionIndex >= 0) {
      e.preventDefault()
      ajouterType(suggestions[selectedSuggestionIndex])
    }
  }

  const ajouterType = (type) => {
    if (type && !formData.typesDeLieux.includes(type)) {
      setFormData({ 
        ...formData, 
        typesDeLieux: [...formData.typesDeLieux, type] 
      })
    }
    setTypeInput('')
    setShowTypeSuggestions(false)
    setSelectedSuggestionIndex(-1)
  }

  const retirerType = (type) => {
    setFormData({ 
      ...formData, 
      typesDeLieux: formData.typesDeLieux.filter(t => t !== type) 
    })
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!formData.nomLieu || formData.typesDeLieux.length === 0 || !formData.ville) {
      setStatus('error')
      return
    }

    setLoading(true)

    try {
      const { error } = await supabase
        .from('contributions')
        .insert([{
          nom_lieu: formData.nomLieu,
          types_de_lieux: formData.typesDeLieux.join(', '),
          ville: formData.ville,
          description: formData.description,
          email: formData.email,
          statut: 'en_attente',
          created_at: new Date().toISOString()
        }])

      if (error) throw error

      setStatus('success')
      setFormData({
        nomLieu: '',
        typesDeLieux: [],
        ville: '',
        description: '',
        email: ''
      })
    } catch (error) {
      console.error('Erreur:', error)
      setStatus('error')
    } finally {
      setLoading(false)
    }
  }

  const typesSuggestions = getTypeSuggestions()

  return (
    <div className="min-h-screen bg-gray-50 p-4">
      <div className="w-[95%] max-w-[95rem] mx-auto">
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="mb-6">
            <h1 className="text-3xl font-bold text-gray-800">Contribuer à Hexa Index</h1>
            <p className="text-gray-600 mt-2">
              Vous connaissez une ressource qui n'est pas encore référencée ? Proposez-la !
            </p>
            <div className="mt-4">
              <MainMenu />
            </div>
          </div>

          {status === 'success' && (
            <div className="bg-green-50 border border-green-200 rounded-lg p-4 mb-6 flex items-start gap-3">
              <CheckCircle className="text-green-600 mt-0.5" size={20} />
              <div>
                <h3 className="font-semibold text-green-800">Contribution envoyée !</h3>
                <p className="text-sm text-green-700 mt-1">
                  Merci pour votre contribution. Elle sera examinée et ajoutée prochainement.
                </p>
              </div>
            </div>
          )}

          {status === 'error' && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6 flex items-start gap-3">
              <AlertCircle className="text-red-600 mt-0.5" size={20} />
              <div>
                <h3 className="font-semibold text-red-800">Erreur</h3>
                <p className="text-sm text-red-700 mt-1">
                  Veuillez remplir tous les champs obligatoires.
                </p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-sm font-medium mb-2">
                Nom du lieu <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={formData.nomLieu}
                onChange={(e) => setFormData({ ...formData, nomLieu: e.target.value })}
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Ex: Atelier Supersérigraphie"
                required
              />
            </div>

            <div className="relative">
              <label className="block text-sm font-medium mb-2">
                Type(s) de lieu <span className="text-red-500">*</span>
                {typesSuggestions.length > 0 && (
                  <span className="text-xs text-gray-500 ml-2">
                    (Utilisez Tab ou ↓↑ pour sélectionner)
                  </span>
                )}
              </label>
              <input
                type="text"
                value={typeInput}
                onChange={(e) => {
                  setTypeInput(e.target.value)
                  setShowTypeSuggestions(true)
                  setSelectedSuggestionIndex(-1)
                }}
                onKeyDown={handleTypeInputKeyDown}
                onFocus={() => setShowTypeSuggestions(true)}
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Rechercher un type de lieu..."
              />
              {showTypeSuggestions && typeInput && (
                <div className="absolute z-10 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
                  {typesSuggestions.map((cat, index) => (
                    <div
                      key={cat}
                      onClick={() => ajouterType(cat)}
                      className={`px-4 py-2 cursor-pointer ${
                        index === selectedSuggestionIndex 
                          ? 'bg-blue-100' 
                          : 'hover:bg-blue-50'
                      }`}
                    >
                      {cat}
                      {index === 0 && typesSuggestions.length > 0 && (
                        <span className="text-xs text-gray-500 ml-2">(Tab)</span>
                      )}
                    </div>
                  ))}
                </div>
              )}
              <div className="flex flex-wrap gap-2 mt-2">
                {formData.typesDeLieux.map(type => {
                  const color = getColorForType(type)
                  return (
                    <span 
                      key={type} 
                      style={{ backgroundColor: color, color: '#202020ff' }}
                      className="px-3 py-1 rounded-full text-sm flex items-center gap-2"
                    >
                      {type}
                      <X size={14} className="cursor-pointer" onClick={() => retirerType(type)} />
                    </span>
                  )
                })}
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">
                Ville <span className="text-red-500">*</span>
              </label>
              <select
                value={formData.ville}
                onChange={(e) => setFormData({ ...formData, ville: e.target.value })}
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                required
              >
                <option value="">Sélectionnez une ville...</option>
                {villes.map(ville => (
                  <option key={ville} value={ville}>
                    {ville}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">
                Description / Informations complémentaires
              </label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent min-h-[120px]"
                placeholder="Ajoutez des détails utiles : adresse, site web, horaires, spécialités..."
              />
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">
                Votre email (optionnel)
              </label>
              <input
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="votre@email.com"
              />
              <p className="text-xs text-gray-500 mt-1">
                Pour être tenu au courant de l'ajout de votre contribution
              </p>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 flex items-center justify-center gap-2 disabled:bg-gray-400 disabled:cursor-not-allowed font-medium"
            >
              {loading ? (
                'Envoi en cours...'
              ) : (
                <>
                  <Send size={20} />
                  Envoyer la contribution
                </>
              )}
            </button>
          </form>
        </div>

        <div className="bg-blue-50 border border-blue-200 rounded-lg p-6">
          <h3 className="font-semibold text-blue-900 mb-2">Pourquoi contribuer ?</h3>
          <p className="text-sm text-blue-800">
            Hexa Index est une base collaborative qui vit grâce aux contributions de la communauté. 
            En partageant vos découvertes, vous aidez d'autres graphistes à trouver les ressources 
            dont ils ont besoin partout en France !
          </p>
        </div>
      </div>
    </div>
  )
}